package caddyfile

import (
	"strconv"
	"strings"
)

// import token placeholder shapes. Only a token whose entire text is
// a single placeholder is substituted; a placeholder adjacent to other
// text (for example "https://{args[0]}" or "{{args[0]}}") is left
// literal.
const (
	argsPrefix    = "{args["
	argsSuffix    = "]}"
	argsDepPrefix = "{args."
	argsDepSuffix = "}"
)

// argsPlaceholderKind classifies a token that is exactly one import
// argument placeholder.
type argsPlaceholderKind int

const (
	argsNotPlaceholder argsPlaceholderKind = iota
	argsScalar                            // {args[N]} or the deprecated {args.N}
	argsVariadic                          // {args[:]}, {args[N:]}, {args[:M]}, {args[N:M]}
)

// classifyArgsPlaceholder reports whether text is, as a whole token,
// an argument placeholder and, if so, which kind. It does not validate
// the index against the number of available arguments.
func classifyArgsPlaceholder(text string) (argsPlaceholderKind, string, bool) {
	if strings.HasPrefix(text, argsPrefix) && strings.HasSuffix(text, argsSuffix) && len(text) > len(argsPrefix)+len(argsSuffix) {
		spec := text[len(argsPrefix) : len(text)-len(argsSuffix)]
		if strings.Contains(spec, ":") {
			return argsVariadic, spec, true
		}
		return argsScalar, spec, true
	}
	// deprecated {args.N} form
	if strings.HasPrefix(text, argsDepPrefix) && strings.HasSuffix(text, argsDepSuffix) && len(text) > len(argsDepPrefix)+len(argsDepSuffix) {
		spec := text[len(argsDepPrefix) : len(text)-len(argsDepSuffix)]
		if !strings.Contains(spec, ":") && !strings.Contains(spec, "{") && !strings.Contains(spec, "}") {
			return argsScalar, spec, true
		}
	}
	return argsNotPlaceholder, "", false
}

// expandArgsPlaceholder substitutes a single whole-token argument
// placeholder with the argument(s) it refers to. Variadic placeholders
// expand, in declaration order, into zero or more tokens sharing the
// metadata of token. Undeclared, negative and out-of-bounds references
// are an error located at the placeholder token itself.
func expandArgsPlaceholder(token Token, args []string) ([]Token, error) {
	kind, spec, ok := classifyArgsPlaceholder(token.Text)
	if !ok {
		// adjacent text, ordinary or escaped braces: keep the token literal
		return []Token{token}, nil
	}

	switch kind {
	case argsScalar:
		index, err := strconv.Atoi(spec)
		if err != nil {
			return nil, tokenErrf(token, "import argument placeholder %s has an invalid index %q", token.Text, spec)
		}
		if index < 0 {
			return nil, tokenErrf(token, "import argument placeholder %s has a negative index", token.Text)
		}
		if index >= len(args) {
			return nil, tokenErrf(token, "import argument placeholder %s index is out of bounds, only %d argument(s) were given to the import", token.Text, len(args))
		}
		token.Text = args[index]
		return []Token{token}, nil

	case argsVariadic:
		start, end, err := parseVariadicBounds(spec, len(args))
		if err != nil {
			return nil, tokenErrf(token, "import argument placeholder %s: %v", token.Text, err)
		}
		out := make([]Token, 0, end-start)
		for _, arg := range args[start:end] {
			t := token
			t.Text = arg
			out = append(out, t)
		}
		return out, nil
	}

	return []Token{token}, nil
}

// parseVariadicBounds parses the "start:end" spec of a variadic
// placeholder, defaulting an empty start to 0 and an empty end to the
// number of available arguments.
func parseVariadicBounds(spec string, argCount int) (int, int, error) {
	startSpec, endSpec, found := strings.Cut(spec, ":")
	if !found {
		return 0, 0, strconv.ErrSyntax
	}

	start := 0
	end := argCount
	var err error
	if startSpec != "" {
		start, err = strconv.Atoi(startSpec)
		if err != nil {
			return 0, 0, errInvalidArgsIndex{value: startSpec}
		}
	}
	if endSpec != "" {
		end, err = strconv.Atoi(endSpec)
		if err != nil {
			return 0, 0, errInvalidArgsIndex{value: endSpec}
		}
	}
	if start < 0 {
		return 0, 0, errNegativeArgsIndex{index: start}
	}
	if end < 0 {
		return 0, 0, errNegativeArgsIndex{index: end}
	}
	if start > end {
		return 0, 0, errArgsIndexReversed{start: start, end: end}
	}
	if end > argCount {
		return 0, 0, errArgsIndexOutOfBounds{index: end, argCount: argCount}
	}
	return start, end, nil
}

