// classifyArgsPlaceholder reports whether text is, as a whole token,
// an argument placeholder and, if so, which kind. It does not validate
// the index against the number of available arguments.
func classifyArgsPlaceholder(text string) (argsPlaceholderKind, string, bool) {
	if strings.HasPrefix(text, argsPrefix) && strings.HasSuffix(text, argsSuffix) && len(text) > len(argsPrefix)+len(argsSuffix) {
		spec := text[len(argsPrefix) : len(text)-len(argsSuffix)]
		if strings.Contains(spec, ":") {
			return argsVariadic, spec, true
		}
		return argsScalar, spec, true
	}
	// deprecated {args.N} form
	if strings.HasPrefix(text, argsDepPrefix) && strings.HasSuffix(text, argsDepSuffix) && len(text) > len(argsDepPrefix)+len(argsDepSuffix) {
		spec := text[len(argsDepPrefix) : len(text)-len(argsDepSuffix)]
		if !strings.Contains(spec, ":") && !strings.Contains(spec, "{") && !strings.Contains(spec, "}") {
			return argsScalar, spec, true
		}
	}
	return argsNotPlaceholder, "", false
}

// expandArgsPlaceholder substitutes a single whole-token argument
// placeholder with the argument(s) it refers to. Variadic placeholders
// expand, in declaration order, into zero or more tokens sharing the
// metadata of token. Undeclared, negative and out-of-bounds references
// are an error located at the placeholder token itself.
func expandArgsPlaceholder(token Token, args []string) ([]Token, error) {
	kind, spec, ok := classifyArgsPlaceholder(token.Text)
	if !ok {
