type argsPlaceholderKind int

const (
	argsNotPlaceholder argsPlaceholderKind = iota
	argsScalar                            // {args[N]} or the deprecated {args.N}
	argsVariadic                          // {args[:]}, {args[N:]}, {args[:M]}, {args[N:M]}
