		return 0, 0, errNegativeArgsIndex{index: end}
	}
	if start > end {
		return 0, 0, errArgsIndexReversed{start: start, end: end}
	}
	if end > argCount {
		return 0, 0, errArgsIndexOutOfBounds{index: end, argCount: argCount}
	}
	return start, end, nil
}

