// scalarArgValue resolves one scalar placeholder mark against args,
// rejecting variadic marks used inline and invalid or missing indices.
func scalarArgValue(token Token, mark string, kind argsPlaceholderKind, spec string, args []string) (string, error) {
	if kind == argsVariadic {
		return "", tokenErrf(token, "variadic placeholder %s must be a token on its own", mark)
	}
