				p.withImportExpansion(sourceTokens, importFile, args, blockTokens, blockMapping, nesting)...)
		}
	}

	// splice the imported tokens in the place of the import statement
	// and rewind cursor so Next() will land on first imported token
	p.tokens = append(tokensBefore, append(importedTokens, tokensAfter...)...)
	p.cursor -= len(args) + len(blockTokens) + 1

	return nil
}

// snippetNodeKey is the machine-readable key of a snippet for cycle
// detection, namespaced by the file that defines it.
func snippetNodeKey(t Token) string {
	if t.snippetName != "" {
		return fmt.Sprintf("%s:%s", t.File, t.snippetName)
	}
	return ""
}

// checkActiveImport fails if node is already part of the active import
// chain of the token that triggers the import, reporting a stable,
// readable recursion chain.
func checkActiveImport(trigger Token, node string) error {
	if node == "" {
		return nil
	}
	for _, existing := range trigger.importChain {
		if existing == node {
			chain := append(append([]string{}, trigger.importChain...), node)
			return tokenErrf(trigger, "import cycle detected: %s", strings.Join(chain, " -> "))
		}
	}
	return nil
}

// withImportExpansion annotates sourceTokens with this import level and
// applies argument and block substitution, returning the tokens to
// splice in. nodeKey is the normalized file path or snippet key the
// tokens originate from.
func (p *parser) withImportExpansion(sourceTokens []Token, nodeKey string, args []string,
	blockTokens []Token, blockMapping map[string][]Token, nesting int) []Token {
	// copy the tokens so we don't overwrite p.definedSnippets
	tokensCopy := make([]Token, 0, len(sourceTokens))

	var (
		maybeSnippet   bool
		maybeSnippetId bool
		index          int
	)

	humanImport := fmt.Sprintf("%s:%d (import)", p.File(), p.Line())

	// run the argument replacer on the tokens
	// golang for range slice return a copy of value
	// similarly, append also copy value
	for i, token := range sourceTokens {
		// record this expansion level in the human- and machine-readable chains
		if !slicesContains(token.imports, humanImport) {
			token.imports = append(append([]string{}, token.imports...), humanImport)
		}
		if nodeKey != "" && !slicesContains(token.importChain, nodeKey) {
			token.importChain = append(append([]string{}, token.importChain...), nodeKey)
		}

		// naive way of determine snippets, as snippets definition can only follow name + block
		// format, won't check for nesting correctness or any other error, that's what parser does.
		if !maybeSnippet && nesting == 0 {
			// first of the line
			if i == 0 || isNextOnNewLine(tokensCopy[len(tokensCopy)-1], token) {
				index = 0
			} else {
				index++
			}

			if index == 0 && len(token.Text) >= 3 && strings.HasPrefix(token.Text, "(") && strings.HasSuffix(token.Text, ")") {
				maybeSnippetId = true
			}
		}

		switch token.Text {
		case "{":
			nesting++
			if index == 1 && maybeSnippetId && nesting == 1 {
				maybeSnippet = true
				maybeSnippetId = false
			}
		case "}":
			nesting--
			if nesting == 0 && maybeSnippet {
				maybeSnippet = false
			}
		}
		// if it is {block}, we substitute with all tokens in the block
		// if it is {blocks.*}, we substitute with the tokens in the mapping for the *
		var tokensToAdd []Token
		foundBlockDirective := false
		switch {
		case token.Text == "{block}":
			foundBlockDirective = true
			tokensToAdd = blockTokens
		case strings.HasPrefix(token.Text, "{blocks.") && strings.HasSuffix(token.Text, "}"):
			foundBlockDirective = true
			// {blocks.foo.bar} will be extracted to key `foo.bar`
			blockKey := strings.TrimPrefix(strings.TrimSuffix(token.Text, "}"), "{blocks.")
			tokensToAdd = blockMapping[blockKey]
		}

		if foundBlockDirective {
			if maybeSnippet {
				tokensCopy = append(tokensCopy, token)
			} else {
				tokensCopy = append(tokensCopy, tokensToAdd...)
			}
			continue
		}

		if maybeSnippet {
			// tokens inside a snippet definition are not bound to this
			// import's arguments; they are substituted later, from the
			// snippet's own invocation layer
			tokensCopy = append(tokensCopy, token)
			continue
		}

		replaced, err := substituteArgsToken(token, args)
		if err != nil {
			// surface the failure at the placeholder, with the chain
			p.importErr = err
			replaced = nil
		}
		tokensCopy = append(tokensCopy, replaced...)
	}

	return tokensCopy
}

func slicesContains(s []string, v string) bool {
	for _, item := range s {
		if item == v {
			return true
		}
	}
	return false
}

// doSingleImport lexes the individual file at importFile using the
// per-call snapshot and returns its tokens or an error, if any.
func (p *parser) doSingleImport(importFile string) ([]Token, error) {
	importFile = filepath.Clean(importFile)

	input, err := p.snapshot.read(importFile)
	if err != nil {
		return nil, p.WrapErr(fmt.Errorf("could not import %s: %v", importFile, err))
	}

	// only warning in case of empty files
	if len(input) == 0 || len(strings.TrimSpace(string(input))) == 0 {
		caddy.Log().Warn("Import file is empty", zap.String("file", importFile))
		return []Token{}, nil
	}

	importedTokens, err := allTokens(importFile, input)
	if err != nil {
		return nil, p.WrapErr(fmt.Errorf("could not read tokens while importing %s: %v", importFile, err))
	}

	// Tack the file path onto these tokens so errors show the imported file's name
	// (we use the full, normalized absolute path to avoid bugs: issue #1892)
	for i := range importedTokens {
		importedTokens[i].File = importFile
	}

	return importedTokens, nil
}

