		if token.snippetName != "" {
			humanImport = fmt.Sprintf("%s:%d (import %s)", p.File(), p.Line(), token.snippetName)
		}
		token.imports = append(append([]string{}, token.imports...), humanImport)

		// machine-readable active recursion chain; snippet templates are
		// re-scoped when registered (see begin), so this only marks live
		// expansions
