cd /tmp/cfexp && cat > main.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync"

	"github.com/caddyserver/caddy/v2/caddyconfig/caddyfile"
)

// map-based in-memory reader acting as a file tree
type memReader struct{ files map[string]string }

func (m memReader) ReadFile(p string) ([]byte, error) {
	if c, ok := m.files[p]; ok { return []byte(c), nil }
	return nil, os.ErrNotExist
}
func (m memReader) Glob(pattern string) ([]string, error) {
	var out []string
	dir, pat := filepath.Split(pattern)
	for p := range m.files {
		if filepath.Dir(p) == strings.TrimSuffix(dir, "/") {
			if ok, _ := filepath.Match(pat, filepath.Base(p)); ok {
				out = append(out, p)
			}
		}
	}
	sort.Strings(out)
	return out, nil
}

func sig(blocks []caddyfile.ServerBlock) string {
	var b strings.Builder
	for _, blk := range blocks {
		b.WriteString("K:")
		b.WriteString(strings.Join(blk.GetKeysText(), ","))
		b.WriteString("|")
		for _, s := range blk.Segments {
			for _, t := range s { b.WriteString(t.Text); b.WriteString(".") }
			b.WriteString("/")
		}
		b.WriteString("\n")
	}
	return b.String()
}

func mustParse(tag string, r caddyfile.ImportReader, input string) {
	bs, err := caddyfile.Parse("/root/Caddyfile", []byte(input), r)
	if err != nil { fmt.Printf("%s ERR: %v\n", tag, err); return }
	fmt.Printf("%s OK:\n%s", tag, sig(bs))
}

func main() {
	// 1. args scope: snippet in imported file must NOT see outer args
	r1 := memReader{files: map[string]string{
		"/root/A.caddy": "(s) {\n\tdir {args[0]}\n}\nimport s\n",
	}}
	mustParse("scope1 (outer arg must not leak into later snippet use)", r1, "import A.caddy OUTER\n")

	// nested file must not inherit parent import args
	r1.files["/root/parent.caddy"] = "import child.caddy\n"
	r1.files["/root/child.caddy"] = "respond {args[0]}\n"
	mustParse("scope2 (child sees no arg)", r1, "import parent.caddy LEAK\n")

	// child redeclares its own args via snippet
	r1.files["/root/p2.caddy"] = "(t) {\n\trespond {args[0]}\n}\nimport t childval\n"
	mustParse("scope3 (snippet own arg)", r1, "import p2.caddy\n")

	// 2. placeholders: literal braces, adjacent text, variadic
	r2 := memReader{files: map[string]string{
		"/root/f.caddy": "a plain{brace}\nb esc\\{x\\}\nc inline{args[0]}end\nd {args[:]}\n",
	}}
	mustParse("literal/adjacent/variadic", r2, "import f.caddy one two three\n")

	// empty / spaced / quoted args stay single raw tokens
	r2.files["/root/g.caddy"] = "respond {args[0]}\nrespond {args[1]}\n"
	mustParse("raw-args", r2, "import g.caddy \"\" \"hello world\"\n")

	// 3. undeclared / negative / oob
	r3 := memReader{files: map[string]string{"/root/b.caddy": "x {args[2]}\n"}}
	mustParse("oob", r3, "import b.caddy a\n")
	r3.files["/root/b.caddy"] = "x {args[-1]}\n"
	mustParse("negative", r3, "import b.caddy a\n")

	// 4. glob sorting + no-match success + duplicate import expansion
	r4 := memReader{files: map[string]string{
		"/root/d/z.caddy": "hostz\n",
		"/root/d/a.caddy": "hosta\n",
		"/root/d/m.caddy": "hostm\n",
	}}
	mustParse("glob-sorted", r4, "import d/*.caddy\n")
	mustParse("glob-nomatch", r4, "import d/nope/*.caddy\n")
	mustParse("dup-import", r4, "import d/a.caddy\nimport d/a.caddy\n")

	// 5. cycle readable chain
	r5 := memReader{files: map[string]string{
		"/root/x.caddy": "import y.caddy\n",
		"/root/y.caddy": "import z.caddy\n",
		"/root/z.caddy": "import x.caddy\n",
	}}
	mustParse("cycle", r5, "import x.caddy\n")

	// 6. unreadable / unclosed quote
	r6 := memReader{files: map[string]string{"/root/q.caddy": "respond \"unterminated\n"}}
	mustParse("unclosed-quote", r6, "import q.caddy\n")

	// 7. failure then different tree same top-level name
	mustParse("fail-tree-first", memReader{files: map[string]string{}}, "import missing.caddy\n")
	mustParse("ok-tree-second", memReader{files: map[string]string{"/root/missing.caddy": "newhost\n"}}, "import missing.caddy\n")

	// 8. determinism
	r8 := memReader{files: map[string]string{"/root/d/z.caddy":"z\n","/root/d/a.caddy":"a\n"}}
	out1, e1 := caddyfile.Parse("/root/Caddyfile", []byte("import d/*.caddy\n"), r8)
	out2, e2 := caddyfile.Parse("/root/Caddyfile", []byte("import d/*.caddy\n"), r8)
	fmt.Printf("determinism equal=%v errs=%v,%v\n", sig(out1)==sig(out2), e1, e2)

	// 9. snapshot: reader mutated mid-call can't affect result (reader only called during call);
	// simulate reuse returning changed content across two calls
	mut := &mutReader{ver: "v1"}
	b1, _ := caddyfile.Parse("/root/Caddyfile", []byte("import s.caddy\n"), mut)
	mut.ver = "v2"
	b2, _ := caddyfile.Parse("/root/Caddyfile", []byte("import s.caddy\n"), mut)
	fmt.Printf("snapshot reuse: %s vs %s\n", oneLine(b1), oneLine(b2))

	// 10. concurrent isolation
	var wg sync.WaitGroup
	errs := make([]string, 8)
	for i := range errs {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			rr := memReader{files: map[string]string{"/root/c.caddy": fmt.Sprintf("host%d\n", i)}}
			b, err := caddyfile.Parse("/root/Caddyfile", []byte("import c.caddy\n"), rr)
			if err != nil { errs[i] = err.Error() } else { errs[i] = sig(b) }
		}(i)
	}
	wg.Wait()
	uniq := map[string]int{}
	for _, e := range errs { uniq[e]++ }
	fmt.Printf("concurrent distinct results=%d/%d\n", len(uniq), len(errs))
}

