23	// Argument placeholder shapes. A placeholder is only replaced when
24	// it is a syntactically complete {args[...]} mark: ordinary braces,
25	// doubled (escaped) braces and adjacent text are preserved literally.
26	// A variadic placeholder must occupy a token on its own.
27	const (
28		argsPrefix    = "{args["
29		argsSuffix    = "]}"
30		argsDepPrefix = "{args."
31		argsDepSuffix = "}"
32	)
