34	type argsPlaceholderKind int
35	
36	const (
37		argsNotPlaceholder argsPlaceholderKind = iota
38		argsScalar                             // {args[N]} or the deprecated {args.N}
39		argsVariadic                           // {args[:]}, {args[N:]}, {args[:M]}, {args[N:M]}
40	)
41	
42	// matchArgsPlaceholder reports whether text[start:] begins with a
43	// complete argument placeholder mark and returns the kind, inner spec
44	// and the position just past the match. Doubled braces are treated as
45	// an escaped brace by the caller, not here.
46	func matchArgsPlaceholder(text string, start int) (kind argsPlaceholderKind, spec string, next int, ok bool) {
47		if rest := text[start:]; strings.HasPrefix(rest, argsPrefix) {
48			endRel := strings.Index(rest[len(argsPrefix):], argsSuffix)
49			if endRel < 0 {
50				return argsNotPlaceholder, "", start, false
51			}
52			innerEnd := len(argsPrefix) + endRel
53			spec = rest[len(argsPrefix):innerEnd]
54			if spec == "" {
55				return argsNotPlaceholder, "", start, false
56			}
57			kind = argsScalar
58			if strings.Contains(spec, ":") {
59				kind = argsVariadic
60			}
61			return kind, spec, start + innerEnd + len(argsSuffix), true
62		}
63		// deprecated {args.N} form: a single non-negative index with no
64		// braces or variadic range inside
65		if rest := text[start:]; strings.HasPrefix(rest, argsDepPrefix) {
66			endRel := strings.Index(rest[len(argsDepPrefix):], argsDepSuffix)
67			if endRel < 0 {
68				return argsNotPlaceholder, "", start, false
69			}
70			spec = rest[len(argsDepPrefix) : len(argsDepPrefix)+endRel]
71			if spec == "" || strings.ContainsAny(spec, "{}:") {
72				return argsNotPlaceholder, "", start, false
73			}
74			return argsScalar, spec, start + len(argsDepPrefix) + endRel + len(argsDepSuffix), true
75		}
76		return argsNotPlaceholder, "", start, false
77	}
