83	// variadic placeholder is only valid as the entire token and expands,
84	// in declaration order, into zero or more tokens sharing the metadata
85	// of token. Empty arguments or arguments containing whitespace or
86	// quotes remain a single token: the replacement text is never re-lexed.
87	// Undeclared, negative or out-of-bounds references are reported at the
88	// placeholder token.
89	func substituteArgsToken(token Token, args []string) ([]Token, error) {
90		// a variadic placeholder is only valid as a token on its own
91		if kind, spec, next, ok := matchArgsPlaceholder(token.Text, 0); ok && kind == argsVariadic && next == len(token.Text) {
