25	)
26	
27	type (
28		// lexer is a utility which can get values, token by
29		// token, from a Reader. A token is a word, and tokens
30		// are separated by whitespace. A word can be enclosed
31		// in quotes if it contains whitespace.
32		lexer struct {
33			reader       *bufio.Reader
34			token        Token
35			line         int
36			skippedLines int
37		}
38	
39		// Token represents a single parsable unit.
40		Token struct {
41			File    string
42			imports []string
43			// importChain holds the machine-readable keys of the nested
44			// import expansions (outermost first) that produced this token;
45			// it is used to detect active import cycles without any global
46			// state.
47			importChain   []string
48			Line          int
49			Text          string
50			wasQuoted     rune // enclosing quote character, if any
51			heredocMarker string
52			snippetName   string
53		}
54	)
55	
56	// Tokenize takes bytes as input and lexes it into
57	// a list of tokens that can be parsed as a Caddyfile.
58	// Also takes a filename to fill the token's File as
59	// the source of the tokens, which is important to
60	// determine relative paths for `import` directives.
61	func Tokenize(input []byte, filename string) ([]Token, error) {
62		l := lexer{}
63		if err := l.load(bytes.NewReader(input)); err != nil {
64			return nil, err
65		}
66		var tokens []Token
67		for {
68			found, err := l.next()
69			if err != nil {
70				return nil, err
71			}
72			if !found {
73				break
74			}
75			l.token.File = filename
76			tokens = append(tokens, l.token)
77		}
78		return tokens, nil
79	}
80	
81	// load prepares the lexer to scan an input for tokens.
82	// It discards any leading byte order mark.
83	func (l *lexer) load(input io.Reader) error {
84		l.reader = bufio.NewReader(input)
85		l.line = 1
86	
87		// discard byte order mark, if present
88		firstCh, _, err := l.reader.ReadRune()
89		if err != nil {
90			return err
91		}
92		if firstCh != 0xFEFF {
93			err := l.reader.UnreadRune()
94			if err != nil {
95				return err
96			}
97		}
98	
99		return nil
100	}
101	
102	// next loads the next token into the lexer.
103	// A token is delimited by whitespace, unless
104	// the token starts with a quotes character (")
105	// in which case the token goes until the closing
106	// quotes (the enclosing quotes are not included).
107	// Inside quoted strings, quotes may be escaped
108	// with a preceding \ character. No other chars
109	// may be escaped. The rest of the line is skipped
110	// if a "#" character is read in. Returns true if
111	// a token was loaded; false otherwise.
112	func (l *lexer) next() (bool, error) {
113		var val []rune
114		var comment, quoted, btQuoted, inHeredoc, heredocEscaped, escaped bool
115		var heredocMarker string
116		var quoteOpenLine int
117	
118		makeToken := func(quoted rune) bool {
119			l.token.Text = string(val)
120			l.token.wasQuoted = quoted
121			l.token.heredocMarker = heredocMarker
122			return true
123		}
124	
125		for {
126			// Read a character in; if err then if we had
127			// read some characters, make a token. If we
128			// reached EOF, then no more tokens to read.
129			// If no EOF, then we had a problem.
130			ch, _, err := l.reader.ReadRune()
131			if err != nil {
132				if quoted || btQuoted {
133					quote := '"'
134					if btQuoted {
135						quote = '`'
136					}
137					return false, fmt.Errorf("unterminated quoted value on line #%d, expected closing %q", quoteOpenLine, quote)
138				}
139				if len(val) > 0 {
140					if inHeredoc {
141						return false, fmt.Errorf("incomplete heredoc <<%s on line #%d, expected ending marker %s", heredocMarker, l.line+l.skippedLines, heredocMarker)
142					}
143	
144					return makeToken(0), nil
145				}
146				if err == io.EOF {
147					return false, nil
148				}
149				return false, err
150			}
151	
152			// detect whether we have the start of a heredoc
153			if (!quoted && !btQuoted) && (!inHeredoc && !heredocEscaped) &&
154				len(val) > 1 && string(val[:2]) == "<<" {
155				// a space means it's just a regular token and not a heredoc
156				if ch == ' ' {
157					return makeToken(0), nil
158				}
159	
160				// skip CR, we only care about LF
161				if ch == '\r' {
162					continue
163				}
164	
165				// after hitting a newline, we know that the heredoc marker
166				// is the characters after the two << and the newline.
167				// we reset the val because the heredoc is syntax we don't
168				// want to keep.
169				if ch == '\n' {
170					if len(val) == 2 {
171						return false, fmt.Errorf("missing opening heredoc marker on line #%d; must contain only alphanumeric characters, dashes and underscores; got empty string", l.line)
172					}
173	
174					// check if there's too many <
175					if string(val[:3]) == "<<<" {
176						return false, fmt.Errorf("too many '<' for heredoc on line #%d; only use two, for example <<END", l.line)
177					}
178	
179					heredocMarker = string(val[2:])
180					if !heredocMarkerRegexp.Match([]byte(heredocMarker)) {
181						return false, fmt.Errorf("heredoc marker on line #%d must contain only alphanumeric characters, dashes and underscores; got '%s'", l.line, heredocMarker)
182					}
183	
184					inHeredoc = true
185					l.skippedLines++
186					val = nil
187					continue
188				}
189				val = append(val, ch)
190				continue
191			}
192	
193			// if we're in a heredoc, all characters are read as-is
194			if inHeredoc {
195				val = append(val, ch)
196	
197				if ch == '\n' {
198					l.skippedLines++
199				}
200	
201				// check if we're done, i.e. that the last few characters are the marker
202				if len(val) >= len(heredocMarker) && heredocMarker == string(val[len(val)-len(heredocMarker):]) {
203					// set the final value
204					val, err = l.finalizeHeredoc(val, heredocMarker)
205					if err != nil {
206						return false, err
207					}
208	
209					// set the line counter, and make the token
210					l.line += l.skippedLines
211					l.skippedLines = 0
212					return makeToken('<'), nil
213				}
214	
215				// stay in the heredoc until we find the ending marker
216				continue
217			}
218	
219			// track whether we found an escape '\' for the next
220			// iteration to be contextually aware
221			if !escaped && !btQuoted && ch == '\\' {
222				escaped = true
223				continue
224			}
225	
226			if quoted || btQuoted {
227				if quoted && escaped {
228					// all is literal in quoted area,
229					// so only escape quotes
230					if ch != '"' {
231						val = append(val, '\\')
232					}
233					escaped = false
234				} else {
235					if (quoted && ch == '"') || (btQuoted && ch == '`') {
236						return makeToken(ch), nil
